function R=run_analysis
here=fileparts(mfilename('fullpath')); projectRoot=fileparts(fileparts(here)); addpath(fullfile(projectRoot,'matlab','funcoes')); p=read_project_parameters(fullfile(projectRoot,'dados','parametros.csv'));
Pg=p.generator_active_mw; Pm=Pg/p.generator_efficiency; Paux=p.auxiliary_active_mw; Pnet=Pg-Paux; Sg=p.generator_rating_mva; Vg=p.generator_voltage_kv;
Qg=Pg*tan(acos(p.generator_power_factor)); Qaux=Paux*tan(acos(p.auxiliary_power_factor)); Qnet=Qg-Qaux-p.capacitor_bank_mvar; Snet=hypot(Pnet,Qnet); Igen=Sg*1e6/(sqrt(3)*Vg*1e3); Itr=p.main_transformer_mva*1e6/(sqrt(3)*p.grid_voltage_kv*1e3); Ipoi=Snet*1e6/(sqrt(3)*p.grid_voltage_kv*1e3);
balance=table(Pg,Pm,Paux,Pnet,Qg,Qaux,p.capacitor_bank_mvar,Qnet,Snet,Igen,Itr,Ipoi,'VariableNames',{'P_gerador_MW','P_mecanica_MW','P_aux_MW','P_exportada_MW','Q_gerador_MVAr','Q_aux_MVAr','Q_banco_MVAr','Q_exportada_MVAr','S_exportada_MVA','I_placa_gerador_A','I_transformador_AT_A','I_POI_A'}); writetable(balance,fullfile(projectRoot,'resultados','tabelas','balanco-potencia.csv'));
base=Sg; zgrid=base/p.grid_short_circuit_mva; r=p.main_transformer_r_pu; x=p.main_transformer_x_pu+zgrid; Scc=base/sqrt(r^2+x^2); Icc13=Scc*1e6/(sqrt(3)*Vg*1e3); Icc138=Scc*1e6/(sqrt(3)*p.grid_voltage_kv*1e3);
short=table(base,zgrid,r,x,Scc,Icc13,Icc138,'VariableNames',{'Base_MVA','X_rede_pu','R_trafo_pu','X_total_pu','Scc_MVA','Icc_13k8_A','Icc_138_A'}); writetable(short,fullfile(projectRoot,'resultados','tabelas','curto-circuito.csv'));
fuel=p.biomass_flow_t_h*1000*p.biomass_lhv_mj_kg/3600; steam=fuel*p.boiler_efficiency; annual=fuel*p.annual_operating_hours; Eel=Pg*p.annual_operating_hours; Enet=Pnet*p.annual_operating_hours; Eth=p.process_steam_thermal_mw*p.annual_operating_hours; utile=(Pg+p.process_steam_thermal_mw)/fuel;
energy=table(fuel,steam,p.process_steam_thermal_mw,Pg,Pnet,utile,annual,Eel,Enet,Eth,'VariableNames',{'combustivel_MW','vapor_disponivel_MWth','vapor_util_MWth','geracao_bruta_MW','exportacao_liquida_MW','rendimento_util_pu','energia_combustivel_MWh_ano','energia_bruta_MWh_ano','energia_liquida_MWh_ano','vapor_util_MWhth_ano'}); writetable(energy,fullfile(projectRoot,'resultados','tabelas','balanco-energetico.csv'));
build_model; mdl='modelo_cogeracao_dinamico'; load_system(fullfile(projectRoot,'simulink',[mdl '.slx']));
t=(0:0.01:5)'; pref=(Pm/Sg)*ones(size(t)); pref(t>=2.5)=pref(t>=2.5)+0.04; vg=ones(size(t)); vg(t>=1 & t<1+p.fault_duration_s)=p.fault_voltage_pu; vref=ones(size(t));
assignin('base','u_ts',timeseries([pref vg vref zeros(size(t))],t)); simout=sim(mdl,'StopTime','5','ReturnWorkspaceOutputs','on'); log=simout.get('y_log'); data=squeeze(log.Data); if size(data,1)~=numel(log.Time) && size(data,2)==numel(log.Time), data=data'; end; dyn=table(log.Time,data(:,1),data(:,2),data(:,3),data(:,4),data(:,5),data(:,6),data(:,7),'VariableNames',{'time_s','angle_rad','speed_deviation_pu','Pm_pu','Pe_pu','Efd_deviation_pu','Q_pu','Vt_pu'}); writetable(dyn,fullfile(projectRoot,'resultados','tabelas','dinamica-maquina.csv'));
fig=figure('Visible','off'); tiledlayout(3,1); nexttile; plot(dyn.time_s,dyn.speed_deviation_pu,'LineWidth',1.1); grid on; ylabel('Δω (pu)'); title('Resposta a afundamento de tensão e degrau de referência'); nexttile; plot(dyn.time_s,dyn.angle_rad,'LineWidth',1.1); grid on; ylabel('δ (rad)'); nexttile; plot(dyn.time_s,dyn.Efd_deviation_pu,'LineWidth',1.1); grid on; ylabel('ΔEfd (pu)'); xlabel('Tempo (s)'); exportgraphics(fig,fullfile(projectRoot,'resultados','graficos','resposta-dinamica.png')); close(fig);
fig=figure('Visible','off'); bar([Pg Pnet Paux p.process_steam_thermal_mw fuel]); xticklabels({'Geração bruta','Exportação líquida','Auxiliares','Vapor útil','Combustível'}); ylabel('MW / MWth'); grid on; title('Balanço energético nominal'); exportgraphics(fig,fullfile(projectRoot,'resultados','graficos','balanco-energetico.png')); close(fig);
R=struct('P_exportada_MW',Pnet,'Q_exportada_MVAr',Qnet,'Scc_MVA',Scc,'Icc_13k8_A',Icc13,'combustivel_MW',fuel,'rendimento_util_pu',utile,'energia_liquida_MWh_ano',Enet,'dinamica',dyn);
end
